import React from "react";
import { useNavigate } from "react-router-dom";
import "./HomePage.css";

function HomePage({ availableSlots }) {
  const navigate = useNavigate();

  const handleBookNow = () => {
    if (availableSlots > 0) {
      navigate("/booking");
    } else {
      alert("No slots available!");
    }
  };

  return (
    <div className="homepage">
      {/* Navbar */}
      <div className="navbar">
        <h2 className="navbar-title">🚗 Parking Slot System</h2>
        <div className="navbar-user">Welcome, User</div>
      </div>

      <div className="main">
        {/* Sidebar */}
        <div className="sidebar">
          <h3 className="sidebar-title">Menu</h3>
          <button onClick={() => navigate("/")}>Home</button>
          <button onClick={() => navigate("/profile")}>Profile</button>
          <button onClick={() => navigate("/about")}>About</button>
          <button onClick={() => navigate("/settings")}>Settings</button>
          <hr />
          <button onClick={() => navigate("/booking")}>Booking</button>
          <button onClick={() => navigate("/payment")}>Payment</button>
          <button onClick={() => navigate("/success")}>Success</button>
        </div>

        {/* Content */}
        <div className="content">
          <h1>Parking Slot Dashboard</h1>
          <h2>Available Slots: <span className="slot-count">{availableSlots}</span></h2>
          <button className="book-btn" onClick={handleBookNow}>
            Book Now
          </button>
        </div>
      </div>
    </div>
  );
}

export default HomePage;
